            && count((array) ($matrix['repository_refs'] ?? [])) >= 5
            && count((array) ($matrix['domain_repository_refs'] ?? [])) >= 3
            && count((array) ($matrix['agent_template_refs'] ?? [])) >= 1
            && count((array) ($matrix['connector_candidates'] ?? [])) >= 1
            && count((array) ($matrix['skills'] ?? [])) >= 5
